solution.javascript:
function wallsAndGates(rooms) {
  const m = rooms.length, n = rooms[0].length, INF = 2147483647;
  const q = [];
  for (let r=0;r<m;r++) for (let c=0;c<n;c++) if (rooms[r][c]===0) q.push([r,c]);
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
  let dist = 0;
  while (q.length) {
    const size = q.length;
    for (let i=0;i<size;i++) {
      const [r,c] = q.shift();
      for (const [dr,dc] of dirs) {
        const nr = r+dr, nc = c+dc;
        if (nr>=0&&nr<m&&nc>=0&&nc<n&&rooms[nr][nc]===INF) { rooms[nr][nc]=dist+1; q.push([nr,nc]); }
      }
    }
    dist++;
  }
}

solution.cpp:
void wallsAndGates(vector<vector<int>>& rooms) {
    int m = rooms.size(), n = rooms[0].size(), INF = 2147483647;
    queue<pair<int,int>> q;
    for (int r=0;r<m;r++) for (int c=0;c<n;c++) if (rooms[r][c]==0) q.push({r,c});
    int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}}, dist = 0;
    while (!q.empty()) {
        int sz = q.size();
        while (sz--) {
            auto [r,c] = q.front(); q.pop();
            for (int d=0;d<4;d++) {
                int nr = r+dirs[d][0], nc = c+dirs[d][1];
                if (nr>=0&&nr<m&&nc>=0&&nc<n&&rooms[nr][nc]==INF) { rooms[nr][nc]=dist+1; q.push({nr,nc}); }
            }
        }
        dist++;
    }
}
